-- =============================================================================
-- V1 : IDENTITY  (users, roles, user_roles, login_history, audit_logs)
-- -----------------------------------------------------------------------------
-- Conventions used by every migration in this project:
--   * BIGINT GENERATED BY DEFAULT AS IDENTITY  -> modern SQL standard primary key
--     (better than BIGSERIAL: the sequence belongs to the column, it cannot be
--     orphaned, and "BY DEFAULT" still allows an explicit id when seeding tests)
--   * TIMESTAMPTZ everywhere, values stored in UTC (NFR-DATA-01)
--   * snake_case names, plural table names (users, not user: "user" is reserved)
--   * every constraint is NAMED (uk_/ck_/fk_/idx_) so error messages and future
--     migrations can reference it
--   * append-only tables (login_history, audit_logs) never store passwords
-- =============================================================================

-- -----------------------------------------------------------------------------
-- users : one row per account (customers, admins, SOC analysts)
-- -----------------------------------------------------------------------------
CREATE TABLE users (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username      VARCHAR(50)  NOT NULL,
    email         VARCHAR(120) NOT NULL,
    -- BCrypt hashes are 60 characters; 100 leaves room for a future algorithm.
    -- A plaintext password must NEVER fit in this column design.
    password_hash VARCHAR(100) NOT NULL,
    full_name     VARCHAR(120),
    phone         VARCHAR(20),
    status        VARCHAR(20)  NOT NULL DEFAULT 'ACTIVE',
    last_login_at TIMESTAMPTZ,
    created_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    updated_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uk_users_username  UNIQUE (username),
    CONSTRAINT uk_users_email     UNIQUE (email),
    -- The database refuses a value the Java enum does not know: the two can
    -- never silently disagree.
    CONSTRAINT ck_users_status    CHECK (status IN ('ACTIVE', 'LOCKED', 'DISABLED')),
    -- Defence in depth: usernames end up in log files and URLs, so ugly input
    -- (spaces, quotes, percent signs) is rejected at the storage layer too.
    CONSTRAINT ck_users_username_format
        CHECK (username ~ '^[A-Za-z0-9._-]{3,50}$')
);

-- -----------------------------------------------------------------------------
-- roles : lookup table (CUSTOMER, ADMIN, SOC_ANALYST). Rows are seeded in V9.
-- -----------------------------------------------------------------------------
CREATE TABLE roles (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code        VARCHAR(30)  NOT NULL,
    name        VARCHAR(60)  NOT NULL,
    description VARCHAR(255),
    created_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    -- Same shape as every other mutable entity (see BaseEntity in Java): an
    -- administrator may rename a role or edit its description in Phase 8.
    updated_at  TIMESTAMPTZ  NOT NULL DEFAULT now(),
    CONSTRAINT uk_roles_code UNIQUE (code)
);

-- -----------------------------------------------------------------------------
-- user_roles : join table for the many-to-many User <-> Role relationship.
-- It has no extra columns, therefore JPA maps it with @ManyToMany + @JoinTable.
-- PK (user_id, role_id) makes a duplicate role assignment impossible at the
-- database level - not "impossible if the Java code remembers to check".
-- -----------------------------------------------------------------------------
CREATE TABLE user_roles (
    user_id BIGINT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    role_id BIGINT NOT NULL REFERENCES roles (id) ON DELETE RESTRICT,
    PRIMARY KEY (user_id, role_id)
);

-- Reverse lookup ("everybody with the SOC_ANALYST role") needs its own index:
-- a composite PK only accelerates lookups that start with user_id.
CREATE INDEX idx_user_roles_role_id ON user_roles (role_id);

-- -----------------------------------------------------------------------------
-- login_history : append-only authentication trail (FR-AUTH-09)
-- Kept separate from security_events because it has a different shape and a
-- different retention period (see package com.yak.minisoc.audit).
-- -----------------------------------------------------------------------------
CREATE TABLE login_history (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    -- SET NULL: deleting a user must not erase the evidence that the login
    -- happened. user_id becomes NULL while username keeps the trace.
    user_id        BIGINT REFERENCES users (id) ON DELETE SET NULL,
    -- The username that was TYPED. For a failed login of a non-existing account
    -- this is the only identifier we have - precisely what brute force looks like.
    username       VARCHAR(50)  NOT NULL,
    success         BOOLEAN      NOT NULL,
    failure_reason VARCHAR(50),
    source_ip      VARCHAR(45),          -- 45 chars fits an IPv6 address
    user_agent     VARCHAR(512),
    occurred_at    TIMESTAMPTZ  NOT NULL DEFAULT now(),
    -- Data-quality invariant: a successful login has no failure reason, and a
    -- failed one must say why. Allowed reasons:
    --   BAD_CREDENTIALS | UNKNOWN_USER | ACCOUNT_LOCKED | ACCOUNT_DISABLED
    CONSTRAINT ck_login_history_reason
        CHECK ((success AND failure_reason IS NULL)
            OR (NOT success AND failure_reason IS NOT NULL))
);

CREATE INDEX idx_login_history_user_time     ON login_history (user_id, occurred_at DESC);
CREATE INDEX idx_login_history_username_time ON login_history (username, success, occurred_at DESC);
CREATE INDEX idx_login_history_ip_time       ON login_history (source_ip, occurred_at DESC);
CREATE INDEX idx_login_history_occurred_at   ON login_history (occurred_at DESC);

-- -----------------------------------------------------------------------------
-- audit_logs : who changed what and when (FR-OUT / SDD section 15 + 11.3 T3)
-- Used for administrative and SOC actions (product deleted, incident resolved).
-- Append-only: rows are never updated.
-- -----------------------------------------------------------------------------
CREATE TABLE audit_logs (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    actor_id       BIGINT REFERENCES users (id) ON DELETE SET NULL,
    -- Denormalised on purpose: the log must stay readable even if the account is
    -- later renamed or deleted. An audit trail that can lose its "who" is useless.
    actor_username VARCHAR(50),
    action         VARCHAR(50) NOT NULL,   -- e.g. PRODUCT_CREATED, INCIDENT_RESOLVED
    entity_type    VARCHAR(50),            -- e.g. Product, Order, SecurityIncident
    entity_id      VARCHAR(64),            -- VARCHAR: fits a numeric id or a business code
    description    TEXT,
    old_value      TEXT,                   -- JSON snapshot before the change
    new_value      TEXT,                   -- JSON snapshot after the change
    -- Plain TEXT here (not JSONB): these snapshots are displayed, never queried
    -- with JSON operators. Only security_events.metadata is JSONB (see V5).
    source_ip      VARCHAR(45),
    occurred_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX idx_audit_logs_actor_time ON audit_logs (actor_id, occurred_at DESC);
CREATE INDEX idx_audit_logs_entity     ON audit_logs (entity_type, entity_id);
CREATE INDEX idx_audit_logs_occurred_at ON audit_logs (occurred_at DESC);
